import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"運氣第十七","description":"杭氏易學 - 運氣第十七","frontmatter":{"title":"運氣第十七","description":"杭氏易學 - 運氣第十七"},"headers":[],"relativePath":"classics/hangshi/018.md","filePath":"classics/hangshi/018.md"}'),l={name:"classics/hangshi/018.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"運氣第十七",tabindex:"-1"},[r("運氣第十七 "),e("a",{class:"header-anchor",href:"#運氣第十七","aria-label":"Permalink to “運氣第十七”"},"​")],-1),e("p",null,"運氣升降由於氣，氣之盛衰由於數，數之進退在乎人。聖人作《易》立人極以明人道，言天言地，皆為人言而為人謀。人在天地中，為善為惡，為君子，為小人，皆在人之自為。而氣機之感召，陰陽進退，而數即隨之而消長。積氣成運，積運成象，為殃為祥，皆視所積。積之以漸，非一朝一夕之故。及其至焉，則為泰為否。君子小人之消長，似乎天實為之，命實定之。嗚呼！天豈任其責哉！《易》以象設教，善惡吉凶，無不備著於象。而以陰陽五行生合升降，為之節度。法象於天地，而示人以進德修業之天則，各有數度。此君子以人合天之本，而古聖人經緯天地，燮理陰陽之大用，皆備於此焉。後儒不察，空言性命，而莫知其象，莫悉其數。反以聖人示之陰陽氣運，為小道，為術數，棄置不言。不知《易》以道陰陽，卦象彖爻無論矣，即孔子之《十翼》，亦無一言無一字，不與陰陽度數相密合。觀於納甲納音，而後知五運六氣，皆出於八卦，在在足與《易》象《易》數相發明。欲知《易》之蘊者，不可不深察焉。",-1),e("p",null,"此主運也。客運則以本年所屬五行作初運，輪流而布。",-1),e("p",null,"是為《月令》之氣，年年定局不易，謂之主氣。至於客氣，則從年司天，自正南位起輪布，看主與客相臨，其氣相得則和，不相得則害。",-1),e("p",null,"五運六氣，天地陰陽之橐龠，其傳最古，今惟《內經》言之最詳。聖人作《易》，法象乎天地，近取諸身，遠取諸物。而天地萬物，皆範圍乎運氣之中。所謂造化之機，與吾人身心性命，息息相關。民胞物與，豈空言所濟！讀董子《春秋繁露》、《淮南鴻烈》、揚子《法言》，當知鄙言之非妄也。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
